"              {(() => {
                const selectedUsage = service.transportUsageOptionKey || getTransportUsageOptionKey(service);
                if (selectedUsage === "full-day") {
                  return (
                    <p className="text-[10px] text-amber-400 italic mt-1 leading-normal">
                      ⚠️ Note: Full Day includes 80 km / 8 hours. Usage exceeding this limit will attract extra charges.
                    </p>
                  );
                } else if (selectedUsage === "half-day") {
                  return (
                    <p className="text-[10px] text-amber-400 italic mt-1 leading-normal">
                      ⚠️ Note: Half Day includes 40 km / 4 hours. Usage exceeding this limit will attract extra charges.
                    </p>
                  );
                }
                return (
                  <p className="text-[10px] text-slate-400 italic mt-1 leading-normal">
                    ⚠️ Note: Full Day includes 80 km / 8 hours and Half Day includes 40 km / 4 hours. Usage exceeding these limits will attract extra charges.
                  </p>
                );
              })()}"

